package cn.richie696.component.secret.provider.pkcs11;
import org.springframework.boot.context.properties.ConfigurationProperties; import java.util.LinkedHashMap; import java.util.Map; import java.util.List;
@ConfigurationProperties(prefix=Pkcs11SecretProperties.PREFIX) public class Pkcs11SecretProperties {
    public static final String PREFIX="platform.component.secret.pkcs11"; private String library; private Integer slot; private String tokenLabel; private char[] pin=new char[0]; private String signingAlgorithm="SHA256withRSA"; private Map<String,String> keyBindings=new LinkedHashMap<>(); private Map<String,List<String>> verificationKeyBindings=new LinkedHashMap<>();
    public String getLibrary(){return library;} public void setLibrary(String v){library=v;} public Integer getSlot(){return slot;} public void setSlot(Integer v){slot=v;} public String getTokenLabel(){return tokenLabel;} public void setTokenLabel(String v){tokenLabel=v;} public char[] getPin(){return pin.clone();} public void setPin(char[] v){char[] previous=pin;pin=v==null?new char[0]:v.clone();if(previous!=null)java.util.Arrays.fill(previous,'\0');} public String getSigningAlgorithm(){return signingAlgorithm;} public void setSigningAlgorithm(String v){signingAlgorithm=v==null||v.isBlank()?"SHA256withRSA":v;} public Map<String,String> getKeyBindings(){return Map.copyOf(keyBindings);} public void setKeyBindings(Map<String,String> v){keyBindings=v==null?new LinkedHashMap<>():new LinkedHashMap<>(v);} public Map<String,List<String>> getVerificationKeyBindings(){Map<String,List<String>> copy=new LinkedHashMap<>();verificationKeyBindings.forEach((k,v)->copy.put(k,v==null?List.of():List.copyOf(v)));return Map.copyOf(copy);} public void setVerificationKeyBindings(Map<String,List<String>> v){verificationKeyBindings=new LinkedHashMap<>();if(v!=null)v.forEach((k,values)->verificationKeyBindings.put(k,values==null?List.of():List.copyOf(values)));}
}
